#include <cstddef>
#include <cstdint>
static void put(std::uint8_t*out,std::size_t i,std::int32_t x){auto b=static_cast<std::uint32_t>(x);for(int k=0;k<4;k++)out[i*4+k]=static_cast<std::uint8_t>(b>>(8*k));}
extern "C" std::int64_t non_preemptive_priority_scheduling(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<4||v[0]<1||v[0]>10||n!=1+3*static_cast<std::size_t>(v[0]))return -1;int count=(int)v[0],arr[10],burst[10],pri[10],done[10]={};for(int i=0;i<count;i++){auto a=v[1+3*i],b=v[2+3*i],p=v[3+3*i];if(a<0||a>20||b<1||b>10||p<0||p>10)return -1;arr[i]=(int)a;burst[i]=(int)b;pri[i]=(int)p;for(int j=0;j<i;j++)if(pri[j]==pri[i])return -1;}if(!out||cap<(std::size_t)count*4)return -2;int now=0,z=0;while(z<count){int pick=-1;for(int i=0;i<count;i++)if(!done[i]&&arr[i]<=now&&(pick<0||pri[i]<pri[pick]||(pri[i]==pri[pick]&&arr[i]<arr[pick])))pick=i;if(pick<0){int next=100000;for(int i=0;i<count;i++)if(!done[i]&&arr[i]<next)next=arr[i];now=next;continue;}done[pick]=1;put(out,z++,pick);now+=burst[pick];}return count*4;}
